public static String compress(String str) {
    StringBuilder sb = new StringBuilder();
    int count = 1;
    char curr = str.charAt(0);
    for (int i = 1; i < str.length(); i++) {
        if (str.charAt(i) == curr) {
            count++;
        } else {
            sb.append(count).append(curr);
