public class Permute {
    public List<List<Integer>> permute(int[] nums) {
        if (nums.length == 1) {
            List<List<Integer>> result = new ArrayList<>();
            List<Integer> list = new ArrayList<>();
            list.add(nums[0]);
            result.add(list);
            return result;
        } else {
            List<List<Integer>> permutations = new ArrayList<>();
            for (int i = 0; i < nums.length; i++) {
                int num = nums[i];
                List<Integer> rest = Arrays.asList(nums).subList(0, i)
                    .stream()
                    .collect(Collectors.toList());
                List<Integer> suffix = Arrays.asList(nums).subList(i + 1, nums.length)
                    .stream()
                    .collect(Collectors.toList());
                permutations.addAll(permute(rest));
                permutations.addAll(permute(suffix));
            }
            return permutations;
        }
    }
}
