public int findLargestSubstring(List<String> strings) {
  int[] histogram = new int[26]; // hash table to keep track of letter frequencies
  int largestSubstring = 0; // maximum length of the largest substring

  for (String string : strings) {
    Arrays.fill(histogram, 0); // reset the histogram for each string

    for (char letter : string.toCharArray()) {
      histogram[letter - 'A']++; // update the histogram
    }

    int currentSubstring = 0; // current length of the substring
    for (char letter : string.toCharArray()) {
      if (histogram[letter - 'A'] > 0) {
        currentSubstring++; // increment the substring length
      } else {
        largestSubstring = Math.max(largestSubstring, currentSubstring); // update the maximum substring length
        currentSubstring = 0; // reset the substring length
      }
    }

    largestSubstring = Math.max(largestSubstring, currentSubstring); // update the maximum substring length
  }

  return largestSubstring;
}

