public int findLargestSubstring(List<String> strings) {
    // Find the largest string X that can be found as a substring of any of the given strings
    // or its inverse
    int maxLength = 0;
    for (String string : strings) {
        if (string.length() > maxLength) {
            maxLength = string.length();
        }
    }

    // Iterate over each substring of length maxLength
    for (int i = 0; i < maxLength; i++) {
        String substring = strings.get(0).substring(i, i + maxLength);
        boolean foundSubstring = true;
        for (String string : strings) {
            if (!string.contains(substring) && !string.contains(substring.reverse())) {
                foundSubstring = false;
                break;
            }
        }
        if (foundSubstring) {
            return maxLength;
        }
    }
    return 0;
}
