public int findLargestSubstring(List<String> strings) {
    if (strings.isEmpty()) {
        return 0;
    }

    int maxLength = 0;
    for (String string : strings) {
        maxLength = Math.max(maxLength, string.length());
    }

    for (int i = 0; i < maxLength; i++) {
        for (String string : strings) {
            if (string.contains(string.substring(i, i + 1))) {
                maxLength = i + 1;
            }
        }
    }

    return maxLength;
}
