public static int maxRegions(int N) {
  // Base case: if N is 1, there are 2 regions (the entire plane and nothing)
  if (N == 1) { return 2; }

  // Otherwise, the maximum number of regions is the maximum X such that N - X is odd
  for (int X = 1; X <= N - 1; X++) {
    if (N - X % 2 == 1) { return X + 1; }
  }

  // If the loop completes without finding an X that satisfies the condition, there is no solution
  return -1;
}
