private static boolean adjacent(int[] start, int[] end, int n) {
    // Check if the starting and ending n-tersections are adjacent
    if (Math.abs(start[0] - end[0]) > 1 || Math.abs(start[1] - end[1]) > 1) {
        return false;
    }

    // Check if the starting and ending n-tersections are not the same
    if (start[0] == end[0] && start[1] == end[1]) {
        return false;
    }

    return true;
}

private static boolean validPath(int[] path, int n) {
    // Check if the path is not null
    if (path == null) {
        return false;
    }

    // Check if the path has the correct length
    if (path.length != n + 1) {
        return false;
    }

    // Check if the first and last elements of the path are adjacent
    if (!adjacent(new int[]{path[0], path[1]}, new int[]{path[n], path[n + 1]}, n)) {
        return false;
    }

    return true;
}
