package kwic;

import java.util.Arrays;

public class Q7 {

    public static String appx(String word1, String word2) {
        int[] counts = new int[26];
        int total = 0;

        for (int i = 0; i < word1.length(); i++) {
            counts[word1.charAt(i) - 'a']++;
            total++;
        }

        for (int i = 0; i < word2.length(); i++) {
            counts[word2.charAt(i) - 'a']--;
            total--;
        }

        int gcd = findGcd(counts);
        for (int i = 0; i < 26; i++) {
            counts[i] = counts[i] / gcd;
        }

        return Arrays.stream(counts).mapToObj(String::valueOf).reduce((a, b) -> a + "/" + b).get();
    }

    private static int findGcd(int[] arr) {
        int gcd = arr[0];
        for (int i = 1; i < arr.length; i++) {
            gcd = (arr[i] == 0) ? gcd : gcd(gcd, arr[i]);
        }
        return gcd;
    }

    private static int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }
}

