// Helper method to determine the day of the week
private static int getDayOfWeek(String year, String month, String day) {
  int dayOfWeek = 0;
  int monthNumber = getMonthNumber(month);
  int century = Integer.parseInt(year.substring(0, 2));
  int yearNumber = Integer.parseInt(year.substring(2));
  if (monthNumber == 1 || monthNumber == 2) {
    yearNumber = yearNumber - 1;
  }
  int adjustedYearNumber = yearNumber + (century / 4 - century / 100 + century / 400);
  dayOfWeek = (adjustedYearNumber + (adjustedYearNumber / 4) + (adjustedYearNumber / 400) - (adjustedYearNumber / 100) + (int)(monthNumber * 2.5) + (int)day) % 7;
  return dayOfWeek;
}

// Helper method to determine the month number
private static int getMonthNumber(String month) {
  switch (month) {
    case "01":
