public int minTime(int n, int[][] edges, boolean[] hasApple) {
  // Initialize the 0th node as the starting node
  int startNode = 0;

  // Initialize the visited and distance arrays
  boolean[] visited = new boolean[n];
  int[] distance = new int[n];
  Arrays.fill(distance, -1);

  // Set the distance and visited arrays for the 0th node
  distance[startNode] = 0;
  visited[startNode] = true;

  // Create a queue for the BFS
  Queue<Integer> queue = new LinkedList<>();
  queue.add(startNode);

  // Loop through the queue until it is empty
  while (!queue.isEmpty()) {
    // Get the size of the queue
    int queueSize = queue.size();

    // Loop through the queue
    for (int i = 0; i < queueSize; i++) {
      // Get the current node
      int currNode = queue.poll();

      // Loop through the neighbors of the current node
      for (int neighbor : edges[currNode]) {
        // If the neighbor has not been visited and it has an apple
        if (!visited[neighbor] && hasApple[neighbor]) {
          // Set the distance and visited arrays for the neighbor
          distance[neighbor] = distance[currNode] + 1;
          visited[neighbor] = true;

          // Add the neighbor to the queue
          queue.add(neighbor);
        }
      }
    }
  }

  // Return the minimum distance to collect all the apples
  return distance[startNode];
}
