    Queue<Integer> queue = new LinkedList<>();
    queue.offer(0);
    while (!queue.isEmpty()) {
        int curNode = queue.poll();
        for (int neighbor : edges[curNode]) {
            if (hasApple[neighbor]) {
                dist[neighbor] = Math.min(dist[neighbor], dist[curNode] + 1);
            }
            if (dist[neighbor] != Integer.MAX_VALUE) {
                queue.offer(neighbor);
            }
        }
    }

    // Find the minimum time
    int minTime = Integer.MAX_VALUE;
    for (int d : dist) {
        minTime = Math.min(minTime, d);
    }
    return minTime;
