public int minTime(int n, int[][] edges, boolean[] hasApple) {
  int[] distance = new int[n];
  for (int i = 0; i < n; i++) {
    distance[i] = -1;
  }
  distance[0] = 0;

  for (int i = 0; i < n; i++) {
    for (int[] edge : edges) {
      if (hasApple[edge[1]]) {
        distance[edge[0]] = Math.min(distance[edge[0]], distance[edge[1]] + 1);
      }
    }
  }

  int minTime = 0;
  for (int i = 0; i < n; i++) {
    if (distance[i] != -1) {
      minTime = Math.max(minTime, distance[i]);
    }
  }

  return minTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
  // Initialize distance and visited arrays
  int[] distance = new int[n];
  boolean[] visited = new boolean[n];

  // Breadth-first search to find the shortest path to all apples
  Queue<Integer> queue = new LinkedList<>();
  queue.add(0);
  visited[0] = true;
  distance[0] = 0;
  while (!queue.isEmpty()) {
    int current = queue.remove();
    for (int i = 0; i < n; i++) {
      if (edges[current][i] != 0 && !visited[i]) {
        visited[i] = true;
        distance[i] = distance[current] + 1;
        queue.add(i);
      }
    }
  }

  // Sum up the minimum time to reach all apples
  int time = 0;
  for (int i = 0; i < n; i++) {
    if (hasApple[i]) {
      time += distance[i];
    }
  }

  return time;
}

