    // Check if all possible binary strings of length k are substrings of the given string
    for (int i = 0; i < Math.pow(2, k); i++) {
        String binaryString = Integer.toBinaryString(i);
        if (!s.contains(binaryString)) {
            return false;
        }
    }

    return true;
}
