public int calculateMinFibonacciNumbers(int k, int[] fibonacciNumbers, int[] previousFibonacciNumbers) {
  // Base case: if the sum of the Fibonacci numbers is equal to k, return the number of Fibonacci numbers
  if (fibonacciNumbers[fibonacciNumbers.length - 1] == k) {
    return fibonacciNumbers.length;
  }

  // If the sum of the Fibonacci numbers is greater than k, return 0
  if (fibonacciNumbers[fibonacciNumbers.length - 1] > k) {
    return 0;
  }

  // Calculate the minimum number of Fibonacci numbers needed
  // to sum up to k using the recurrence relation
  int minFibonacciNumbers = Integer.MAX_VALUE;
  for (int i = fibonacciNumbers.length - 1; i >= 0; i--) {
    if (fibonacciNumbers[i] + previousFibonacciNumbers[i] <= k) {
      minFibonacciNumbers = Math.min(minFibonacciNumbers, calculateMinFibonacciNumbers(k - (fibonacciNumbers[i] + previousFibonacciNumbers[i]), fibonacciNumbers, previousFibonacciNumbers));
    }
  }

  return minFibonacciNumbers + 1;
}

