            StringBuilder currentSubstring = new StringBuilder();

            for (int j = i; j < s.length(); j++) {
                // Add the next character to the current substring
                currentSubstring.append(s.charAt(j));

                // Check if the current substring is already in the map
                if (uniqueSubstrings.containsKey(currentSubstring.toString())) {
                    // If it is, we can stop here
                    break;
                } else {
                    // If it's not, add it to the map and update the maximum number of unique substrings
                    uniqueSubstrings.put(currentSubstring.toString(), 1);
                    maxUniqueSubstrings++;
                }
            }
        }

        return maxUniqueSubstrings;
    }
}

