public int minOperations(String[] logs) {
    // Initialize a set to keep track of the directories we've visited
    Set<String> visited = new HashSet<>();
    // Initialize a stack to keep track of the directories we want to explore
    Stack<String> stack = new Stack<>();
    // Initialize the main folder
    String currentFolder = "/";
    // Iterate through the logs
    for (String log : logs) {
        // If the log is a directory, add it to the stack
        if (log.endsWith("/")) {
            stack.push(log);
        }
        // If the log is a "../" operation, remove the top element from the stack
        else if (log.equals("../")) {
            stack.pop();
        }
        // If the log is a "./" operation, do nothing
        else if (log.equals(".")) {
            continue;
        }
        // If the log is a "dX/" operation, add "/dX" to the current folder
        else {
            currentFolder += log;
        }
        // If the current folder is already visited, return the minimum number of steps
        if (visited.contains(currentFolder)) {
            return visited.size() - visited.indexOf(currentFolder);
        }
        // Add the current folder to the visited set
        visited.add(currentFolder);
    }
    // Return the minimum number of steps
    return visited.size();
}
