private static int permute(int[] A, Set<Integer> requiredSquares) {
    if (requiredSquares.isEmpty()) {
        return 1;
    }
    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if (!requiredSquares.contains(A[i])) {
            continue;
        }
        int[] newA = Arrays.copyOf(A, A.length);
        int[] newRequiredSquares = new HashSet<>(requiredSquares).stream().filter(s -> s != A[i]).mapToInt(j -> j).toArray();
        Arrays.fill(newA, i, A.length, 0);
        count += permute(newA, newRequiredSquares);
    }
    return count;
}
