public static int[] diagonalOrder(int[][] mat) {
    int n = mat.length;
    int[] order = new int[n * n];
    int i = 0;
    for (int d = 0; d < 2 * n - 1; d++) {
        for (int j = d - n + 1; j <= Math.min(d, n - 1); j++) {
            order[i++] = mat[j][d - j];
        }
    }
    return order;
}

