import java.math.BigDecimal;
import java.math.MathContext;
import java.math.RoundingMode;
import java.util.Arrays;
import java.util.Map;
import java.util.stream.Collectors;

public class ProbabilityDistributionEntropy {

    public static double entropy(double[] pmf) {
        Map<Double, BigDecimal> probabilities = Arrays.stream(pmf)
                .boxed()
                .collect(Collectors.toMap(Double::doubleValue, i -> BigDecimal.valueOf(i), (e1, e2) -> e1.add(e2)));

        return probabilities.entrySet()
                .stream()
                .map(entry -> entry.getValue().multiply(
                        BigDecimal.valueOf(Math.log(entry.getValue().toDouble() / probabilities.size())))
                )
                .map(result -> result.setScalb(RoundingMode.HALF_UP, -1))
                .map(result -> result.subtract(result.divide(probabilities.size(), MathContext.DECIMAL64).pow(2)))
                .map(BigDecimal::doubleValue)
                .collect(Collectors.summingDouble(Double::doubleValue)) / Math.log(2);
    }

}
```

