    public static boolean isBoomerang(int[][] points) {
        Arrays.sort(points, (a, b) -> a[0] - b[0]);
        int[][] slope = new int[points.length - 1][];
        for (int i = 0; i < points.length - 1; i++) {
            slope[i][0] = (points[i + 1][1] - points[i][1]) / (points[i + 1][0] - points[i][0]);
            slope[i][1] = (points[i + 1][0] - points[i][0]) * slope[i][0];
