        for (int i = 0; i < slope.length - 1; i++) {
            for (int j = i + 1; j < slope.length; j++) {
                if (slope[i][0] == slope[j][0]) {
                    if (slope[i][1] == slope[j][1] || slope[i][1] - slope[j][1] == 0) {
