    // Loop through all perfect squares less than or equal to n
    for (int i = 1; i * i <= n; i++) {
        perfectSquares.add(i * i);
    }

    // Initialize a variable to keep track of the minimum number of perfect square numbers
    int minSquares = 0;

    // Loop through all numbers from 1 to n
    for (int i = 1; i <= n; i++) {
        // If the number is a perfect square, add it to the set
        if (perfectSquares.contains(i)) {
            minSquares++;
        }
    }

    // Return the minimum number of perfect square numbers
    return minSquares;
