package com.example;

import java.util.*;

public class MinPerfectSquareSum {
    public static int minPerfectSquareSum(int n) {
        // Base case: if n is a perfect square, return 1
        if (n > 0 && Integer.toString(n).matches("\\d+\\d*")) {
            return 1;
        }

        // Initialize a set to store perfect square numbers
        Set<Integer> perfectSquares = new HashSet<>();

        // Initialize a variable to store the minimum number of perfect square numbers
        int minNumber = 0;

        // Loop through the range of perfect square numbers
        for (int i = 1; i <= n; i++) {
            // If the number is a perfect square, add it to the set
            if (i > 0 && Integer.toString(i).matches("\\d+\\d*")) {
                perfectSquares.add(i);
            }

            // If the sum of the numbers in the set is equal to the target number, return the size of the set
            if (perfectSquares.stream().mapToInt(Integer::intValue).sum() == n) {
                minNumber = perfectSquares.size();
                break;
            }
        }

        return minNumber;
    }
}

