    String[] words = s.split(" ");

    // Initialize an empty string to hold the reversed words
    String reversed = "";

    // Iterate over the words and reverse each one
    for (String word : words) {

        // Reverse the current word
        String reversedWord = new StringBuffer(word).reverse().toString();

        // Add the reversed word to the list of reversed words
        reversed += reversedWord + " ";
    }

    // Return the list of reversed words
    return reversed.trim();
